fn all_characters_same(s: &[u8]) -> bool {
    // An empty array or a single-element array is considered to have all identical characters
    if s.len() <= 1 {
        return true;
    }

    // Get the first byte to compare with the rest
    let first_byte = s[0];

    // Check if all bytes in the array are the same as the first byte
    for &byte in s.iter() {
        if byte != first_byte {
            return false;
        }
    }

    true
}